--#api tic80
--@ Vircon32 Lua TIC-80 sync() memory banks Unit Test
--@ sync(mask, bank, tocart) copies tiles (1), sprites (2), map (4), palette (32)
--@ and flags (64) between the cart's banks 0-7 and the RAM. Banks 1-7 come from
--@ the cart's "-- <MAP1>" ... sections; bank 0 is the cart's own data; a bank the
--@ cart lacks reads as zeros (the palette is left alone); tocart = true saves the
--@ RAM into the bank. Map checks go through mget and the RAM mirror at 0x8000.
--@ Results are stored in global variables for automated memory scraping.

number_result1 = 0
number_result2 = 0
number_result3 = 0
number_result4 = 0
number_result5 = 0
number_result6 = 0
number_result7 = 0
number_result8 = 0
number_result9 = 0
number_result10 = 0
number_result11 = 0
number_result12 = 0

function TIC()
    sync(0, 0)                                   -- bank 0 everywhere (frame 2 on: undo the saves below)
    number_result1 = mget(10, 20)                -- Expected: 31 (bank 0)
    sync(4, 1)
    number_result2 = mget(10, 20)                -- Expected: 127 (bank 1)
    number_result3 = peek(0x8000 + 20 * 240 + 10) -- Expected: 127 (the RAM mirror)
    sync(4, 0)
    number_result4 = mget(10, 20)                -- Expected: 31 (back to bank 0)
    sync(4, 1)
    mset(10, 20, 200)
    sync(4, 2, true)                             -- save the edited map into bank 2
    sync(4, 1)
    number_result5 = mget(10, 20)                -- Expected: 127
    sync(4, 2)
    number_result6 = mget(10, 20)                -- Expected: 200 (bank 2 as saved)
    number_result7 = mget(11, 20)                -- Expected: 129 (bank 1 neighbour, saved with it)
    sync(4, 5)
    number_result8 = mget(10, 20)                -- Expected: 0 (bank 5: not in the cart)
    sync(32, 1)
    number_result9 = peek(0x3FC3) * 1000 + peek(0x3FC4) -- Expected: 255000 (palette bank 1: color 1 = ff0000)
    sync(1, 1)
    number_result10 = peek(0x4000)               -- Expected: 33 (tile 0, bank 1: pixels 1,2)
    sync(1, 0)
    number_result11 = peek(0x4000)               -- Expected: 0 (bank 0 has no tiles)
    sync(0, 1)                                   -- everything from bank 1
    number_result12 = mget(0, 0)                 -- Expected: 7
end

